import React, { useState, useEffect } from "react";
import Product from "./Product"; // Import component từ TASK-05

// Kho dữ liệu ảo 20 sản phẩm công nghệ để test giao diện
const mockProductsFromMySQL = [
  { id: 1, name: "Điện thoại iPhone 15 Pro Max 256GB", price: 29500000, category: "DienThoai", image_url: "", percent_off: 10 },
  { id: 2, name: "Laptop MacBook Air M2 8GB/256GB", price: 24990000, category: "Laptop", image_url: "", percent_off: 0 },
  { id: 3, name: "Điện thoại Samsung Galaxy S24 Ultra", price: 26990000, category: "DienThoai", image_url: "", percent_off: 15 },
  { id: 4, name: "Laptop Asus Vivobook 14 X1404ZA", price: 14290000, category: "Laptop", image_url: "", percent_off: 5 },
  { id: 5, name: "Máy tính bảng iPad Air 5 M1 Wifi", price: 15490000, category: "Tablet", image_url: "", percent_off: 8 },
  { id: 6, name: "Tai nghe Bluetooth AirPods Pro Gen 2", price: 5690000, category: "PhuKien", image_url: "", percent_off: 12 },
  { id: 7, name: "Đồng hồ thông minh Apple Watch Series 9", price: 9890000, category: "Watch", image_url: "", percent_off: 0 },
  { id: 8, name: "Điện thoại Xiaomi Redmi Note 13 Pro", price: 6490000, category: "DienThoai", image_url: "", percent_off: 10 },
  { id: 9, name: "Laptop Lenovo Ideapad Slim 3", price: 12890000, category: "Laptop", image_url: "", percent_off: 0 },
  { id: 10, name: "Chuột không dây Logitech MX Master 3S", price: 2350000, category: "PhuKien", image_url: "", percent_off: 5 },
  { id: 11, name: "Bàn phím cơ ASUS ROG Strix Scope", price: 3150000, category: "PhuKien", image_url: "", percent_off: 20 },
  { id: 12, name: "Điện thoại OPPO Reno11 5G", price: 9990000, category: "DienThoai", image_url: "", percent_off: 0 },
  { id: 13, name: "Máy tính bảng Samsung Galaxy Tab S9 FE", price: 10490000, category: "Tablet", image_url: "", percent_off: 7 },
  { id: 14, name: "Tai nghe Chụp Tai Sony WH-1000XM5", price: 6990000, category: "PhuKien", image_url: "", percent_off: 15 },
  { id: 15, name: "Củ sạc nhanh Anker GaNPrime 65W", price: 850000, category: "PhuKien", image_url: "", percent_off: 0 },
  { id: 16, name: "Laptop Dell Inspiron 14 5430", price: 17990000, category: "Laptop", image_url: "", percent_off: 10 },
  { id: 17, name: "Đồng hồ Samsung Galaxy Watch6 LTE", price: 6490000, category: "Watch", image_url: "", percent_off: 18 },
  { id: 18, name: "Loa Bluetooth JBL Charge 5", price: 3650000, category: "PhuKien", image_url: "", percent_off: 5 },
  { id: 19, name: "Pin sạc dự phòng Baseus 20000mAh 22.5W", price: 450000, category: "PhuKien", image_url: "", percent_off: 0 },
  { id: 20, name: "Màn hình Gaming MSI Optix 24 inch", price: 3290000, category: "PhuKien", image_url: "", percent_off: 12 }
];

function ProductList() {
  const [products, setProducts] = useState([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [category, setCategory] = useState("");
  const [loading, setLoading] = useState(false);

  // Hàm xử lý lọc dữ liệu ảo tại local
  const filterMockData = () => {
    setLoading(true);
    
    const filtered = mockProductsFromMySQL.filter((item) => {
      const matchCategory = category === "" || item.category === category;
      const matchSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase());
      return matchCategory && matchSearch;
    });

    setProducts(filtered);
    setLoading(false);
  };

  // Tự động cập nhật danh sách khi thay đổi bộ lọc hoặc từ khóa tìm kiếm
  useEffect(() => {
    filterMockData();
  }, [category]);

  const handleSearchSubmit = (e) => {
    e.preventDefault();
    filterMockData();
  };

  return (
    <div className="container mt-5 mb-5">
      <h2 className="text-center fw-bold mb-4">Khám Phá Sản Phẩm</h2>

      {/* --- THANH TÌM KIẾM & LỌC --- */}
      <form onSubmit={handleSearchSubmit} className="row justify-content-center mb-5">
        <div className="col-md-8 d-flex gap-2">
          <input
            type="text"
            className="form-control shadow-sm"
            placeholder="🔍 Nhập tên sản phẩm công nghệ cần tìm..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
          <select
            className="form-select shadow-sm w-25"
            value={category}
            onChange={(e) => setCategory(e.target.value)}
          >
            <option value="">Tất cả danh mục</option>
            <option value="DienThoai">Điện thoại</option>
            <option value="Laptop">Laptop</option>
            <option value="Tablet">Máy tính bảng</option>
            <option value="Watch">Đồng hồ thông minh</option>
            <option value="PhuKien">Phụ kiện linh kiện</option>
          </select>
          <button type="submit" className="btn btn-dark px-4">Tìm</button>
        </div>
      </form>

      {/* --- LƯỚI SẢN PHẨM --- */}
      {loading ? (
        <div className="text-center mt-4">
          <p className="text-muted fs-5">Đang xử lý dữ liệu...</p>
        </div>
      ) : (
        <div className="row row-cols-1 row-cols-md-2 row-cols-lg-4 g-4">
          {products.length > 0 ? (
            products.map((item) => (
              <Product key={item.id} data={item} />
            ))
          ) : (
            <div className="col-12 text-center mt-4">
              <p className="text-muted fs-5">Không tìm thấy sản phẩm công nghệ nào phù hợp.</p>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export default ProductList;
